<script lang="ts">
  import type { Snippet } from 'svelte'; import type { OpenInProvider } from './providers.js'; import { Bot, Code2, ExternalLink, GitFork, MessageCircle, Search, Sparkles } from '@lucide/svelte'; import { cn } from '../../utils.js'; import { providers } from './providers.js'; import { useOpenInContext } from './context.svelte.js';
  let { provider, class: className = '', children, ...rest }: { provider: OpenInProvider; class?: string; children?: Snippet; [key: string]: unknown } = $props(); const context = useOpenInContext(); const definition = $derived(providers[provider]); const href = $derived(definition.createUrl(context.query));
</script>
{#if href}<a class={cn('flex items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-ring', className)} {href} target="_blank" rel="external noopener noreferrer" role="menuitem" onclick={() => context.setOpen(false)} {...rest}><span class="inline-flex size-4 shrink-0 items-center justify-center text-muted-foreground" aria-hidden="true">{#if provider === 'github'}<GitFork size={16} />{:else if provider === 'cursor'}<Code2 size={16} />{:else if provider === 'scira'}<Search size={16} />{:else if provider === 'v0'}<Sparkles size={16} />{:else if provider === 't3'}<MessageCircle size={16} />{:else}<Bot size={16} />{/if}</span><span class="min-w-0 flex-1">{#if children}{@render children()}{:else}{definition.title}{/if}</span><ExternalLink size={14} class="shrink-0" aria-hidden="true" /></a>{/if}
